import math

def next_Perfect_Square(N):
    """Return the smallest perfect square strictly greater than integer N."""
    # Ensure N is an integer
    if not isinstance(N, int):
        try:
            N = int(N)
        except Exception:
            raise TypeError("N must be an integer") from None

    # For negative N, 0 is the smallest perfect square greater than any negative number
    if N < 0:
        return 0

    m = math.isqrt(N)  # floor(sqrt(N))
    return (m + 1) ** 2

