from functools import lru_cache

def get_max_sum(n):
    """
    Compute the maximum sum defined by:
        f(n) = max( f(n//2) + f(n//3) + f(n//4) + f(n//5), n )
    Uses memoization to avoid recomputing subproblems.

    Parameters:
        n (int): Non‑negative integer for which to compute the value.

    Returns:
        int: The maximum sum achievable for the given n.
    """
    @lru_cache(maxsize=None)
    def f(x):
        if x <= 0:
            return 0
        return max(x, f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5))

    return f(n)

