def sequence(n):
    """Return the n‑th term of the Newman–Conway sequence (1‑indexed)."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n <= 0:
        raise ValueError("n must be a positive integer")
    if n <= 2:
        return 1
    # Use a list to store previously computed terms.
    seq = [0, 1, 1]          # seq[1] = seq[2] = 1
    for i in range(3, n + 1):
        # seq[i] = seq[i - seq[i-1]] + seq[i-1 - seq[i-2]]
        a_i = seq[i - seq[i - 1]] + seq[i - 1 - seq[i - 2]]
        seq.append(a_i)
    return seq[n]

