def dict_depth(d):
    """
    Recursively compute the maximum depth of a dictionary.
    Depth is defined as:
      - 1 for an empty dictionary or a dictionary with no nested dictionaries.
      - n+1 if any nested dictionary has depth n.
    """
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary.")
    max_depth = 1
    for value in d.values():
        if isinstance(value, dict):
            nested_depth = 1 + dict_depth(value)
            if nested_depth > max_depth:
                max_depth = nested_depth
    return max_depth

