    """
    Return True if the list `s` occurs contiguously within the list `l`, otherwise False.
    An empty list is considered a sublist of any list.
    """
    if not isinstance(l, list) or not isinstance(s, list):
        raise TypeError("Both arguments must be lists")
    if not s:
