def comb_sort(nums):
    """Sort a list of elements using Comb Sort and return a new sorted list."""
    arr = list(nums)  # Work on a copy to avoid mutating the original list
    n = len(arr)
    if n <= 1:
        return arr

    gap = n
    shrink_factor = 1.3
    swapped = True

    while gap > 1 or swapped:
        if gap > 1:
            gap = int(gap / shrink_factor)
            if gap < 1:
                gap = 1
        swapped = False
        for i in range(0, n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True
    return arr

