from decimal import Decimal, ROUND_HALF_UP

def invoice_total(lines, coupon=None):
    """Return an invoice total in cents.
    lines is a list of (quantity, unit_price_cents, category) tuples.
    - Tax is 13% on every category except "food", which is not taxed.
    - coupon "SAVE10" takes 10% off the pre-tax subtotal of the non-food lines, at most 2000 cents;
      tax is charged on the discounted amount. Any other coupon raises ValueError.
    - Round once, at the end, to the nearest cent; halves round up.

    invoice_total([(1, 1000, "tools"), (1, 500, "food")], "SAVE10") == 1517
    """
    subtotal_non_food = Decimal('0')
    subtotal_food = Decimal('0')
    for qty, price_cents, category in lines:
        amount = Decimal(qty) * Decimal(price_cents)
        if category == "food":
            subtotal_food += amount
        else:
            subtotal_non_food += amount

    if coupon is None:
        discount = Decimal('0')
    elif coupon == "SAVE10":
        discount_raw = subtotal_non_food * Decimal('0.10')
        discount = discount_raw if discount_raw <= Decimal('2000') else Decimal('2000')
    else:
        raise ValueError("Invalid coupon")

    discounted_non_food = subtotal_non_food - discount
    tax = discounted_non_food * Decimal('0.13')
    total = discounted_non_food + tax + subtotal_food
    rounded_total = total.quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    return int(rounded_total)

