import math

def babylonian_squareroot(number):
    """Return the square root of a non‑negative number using the Babylonian method."""
    if number < 0:
        raise ValueError("Cannot compute square root of a negative number")
    if number == 0 or number == 1:
        return float(number)

    # Initial guess: use the number itself if it's >= 1, otherwise start from 1.
    guess = number if number >= 1 else 1.0
    tolerance = 1e-12
    max_iterations = 1000
    iteration = 0

    while iteration < max_iterations:
        new_guess = 0.5 * (guess + number / guess)
        if abs(new_guess - guess) <= tolerance:
            return new_guess
        guess = new_guess
        iteration += 1

    # If convergence was not reached within the iteration limit, return the best estimate.
    return guess

