import math

def count_binary_seq(n):
    """
    Returns the number of binary sequences of length 2n where the sum of the first
    n bits equals the sum of the last n bits. This is equal to C(2n, n).
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")

    if hasattr(math, "comb"):
        return math.comb(2 * n, n)

    # Fallback implementation for older Python versions
    k = n
    result = 1
    for i in range(1, k + 1):
        result = result * (2 * n - k + i) // i
    return result

