def dict_depth(d):
    """
    Return the maximum depth of nested dictionaries within dictionary `d`.

    The depth is defined as:
        * 1 for a dictionary that contains no nested dictionaries.
        * For a dictionary containing a nested dictionary, its depth is 1 + the
          depth of the deepest nested dictionary.

    Non‑dictionary values are ignored for depth calculation.  If `d` is not a
    dictionary, the function returns 0.
    """
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for value in d.values():
        if isinstance(value, dict):
            depth = 1 + dict_depth(value)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(value, (list, tuple)):
            for item in value:
                if isinstance(item, dict):
                    depth = 1 + dict_depth(item)
                    if depth > max_depth:
                        max_depth = depth
    return max_depth

