def set_left_most_unset_bit(n: int) -> int:
    """
    Return a new integer where the most significant unset (0) bit of the binary
    representation of ``n`` is set to 1. For non‑negative `n`, the function
    considers bits up to the current highest set bit; if all those bits are 1,
    it sets the next higher bit.
    """
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    bit_len = n.bit_length()
    for i in range(bit_len - 1, -1, -1):
        if (n >> i) & 1 == 0:
            return n | (1 << i)
    return n | (1 << bit_len)

